//! `Spectrum` and `SpectrumKind`, `SampledSpectrum`, `SampledWavelengths`, RGB and color spaces.
//!
//! A core crate (ADR 0014, ADR 0015): `#![no_std]` without `alloc`. Light is
//! spectral only, at [`N_SPECTRUM_SAMPLES`] wavelengths per Pixel Sample
//! (ADR 0001), and RGB input becomes spectra through the Jakob–Hanika
//! RGB-to-spectrum table, generated by the build script with `libm`
//! (ADR 0002, arc42 §8.1). The routines are pbrt-v4's
//! (`src/pbrt/util/spectrum.h`, `color.h`, `colorspace.h`), ported
//! faithfully in `f32` (ADR 0001); names follow pbrt-v4, in snake case.
//! pbrt-v4's spectral data and table generator are Apache-2.0, attributed
//! in `NOTICE`.

#![no_std]

mod color;
mod color_space;
mod rgb_to_spectrum;
mod sampled;
pub mod spectra;
mod spectrum;

pub use color::{RGB, RGBSigmoidPolynomial, XYZ};
pub use color_space::RGBColorSpace;
pub use sampled::{
    CIE_Y_INTEGRAL, LAMBDA_MAX, LAMBDA_MIN, N_SPECTRUM_SAMPLES, SampledSpectrum, SampledWavelengths,
};
pub use spectrum::{
    ConstantSpectrum, DenselySampledSpectrum, RGBAlbedoSpectrum, RGBIlluminantSpectrum,
    RGBUnboundedSpectrum, Spectrum, SpectrumKind, inner_product, spectrum_to_photometric,
    spectrum_to_xyz,
};

/// `values` rounded to `f32`, as C++ rounds the `double` literals of
/// pbrt-v4's `float` tables and constants.
const fn narrow_all<const N: usize>(values: [f64; N]) -> [f32; N] {
    let mut out = [0.0; N];
    let mut i = 0;
    while i < N {
        out[i] = narrow(values[i]);
        i += 1;
    }
    out
}

/// `v` rounded to the nearest `f32`, ties to even: C++'s conversion of a
/// `double` literal to `float`.
#[expect(
    clippy::cast_possible_truncation,
    reason = "the rounding C++ applies to pbrt-v4's literals"
)]
const fn narrow(v: f64) -> f32 {
    v as f32
}
